int main(){try{SessionTimelineDocumentCandidate doc(loadGraph("work/roundtrip-11.dmx"));auto discovery=discoverSessionExpressionChainsCandidate(doc.graph(),2237);auto found=std::find_if(discovery.chains.begin(),discovery.chains.end(),[&](const auto&chain){ChannelBinding copy(doc.graph(),chain.copy);return copy.destination.element==32375&&copy.destination.attribute=="scale";});if(found==discovery.chains.end())throw std::runtime_error("scale chain missing");ChannelBinding play(doc.graph(),found->play);auto layer=play.layers.at(0);KeyTrack keys(doc.graph(),doc.graph().elements[layer]);auto local=wireInt(keys.times->values.at(0));int32_t rootTick=local;for(auto it=found->frames.rbegin();it!=found->frames.rend();++it){AnimationTimeFrame frame(doc.graph(),doc.graph().elements[*it]);if(frame.scale!=1)throw std::runtime_error("fixture requires unit scale");rootTick=wrapTicks(uint32_t(rootTick)-uint32_t(frame.offset)+uint32_t(frame.start));}
 std::filesystem::path content=R"(F:\SteamLibrary\steamapps\common\SourceFilmmaker\game\usermod)";std::ifstream file(content/"gameinfo.txt",std::ios::binary);std::string text((std::istreambuf_iterator<char>(file)),{});RetainedSessionSceneCandidate scene(Graph(doc.graph()),2237,gameinfoMountsCandidate(text,content,content.parent_path()),4,true,true);auto before=scene.sample(rootTick);bool missingReported=false;for(const auto&diagnostic:before.missingAssets)for(const auto&reference:diagnostic.references)if(reference=="$basetexture models/mariogamer/awtter/bodytythoon")missingReported=true;if(!missingReported)throw std::runtime_error("missing base texture was not surfaced by scene result");auto missingSummary=sceneMissingAssetSummaryCandidate(before.missingAssets);if(missingSummary.find("Missing texture assets: ")!=0)throw std::runtime_error("missing asset summary not available to editor");auto publish=[&](const Graph&graph){scene.replaceSession(Graph(graph),2237);};float old=wireFloat(keys.values->values.at(0));float changed=old==0.5f?0.75f:0.5f;int32_t movedTick=local;doc.transact([&](auto&staged){return staged.setFloatKey(layer,0,movedTick,changed);},publish);auto after=scene.sample(rootTick);if(before.upload.vertices.size()!=after.upload.vertices.size()||before.upload.indices!=after.upload.indices)throw std::runtime_error("topology changed");size_t count=0;for(size_t i=0;i<before.upload.vertices.size();++i)count+=std::memcmp(&before.upload.vertices[i],&after.upload.vertices[i],sizeof(SceneGpuVertexCandidate))!=0;if(!count)throw std::runtime_error("key edit produced no geometry change");doc.transact([](auto&staged){return staged.undo()!=0;},publish);if(wireInt(KeyTrack(doc.graph(),doc.graph().elements[layer]).times->values[0])!=local)throw std::runtime_error("joint edit undo did not restore key time");auto restored=scene.sample(rootTick);for(size_t i=0;i<before.upload.vertices.size();++i)if(std::memcmp(&before.upload.vertices[i],&restored.upload.vertices[i],sizeof(SceneGpuVertexCandidate)))throw std::runtime_error("undo geometry mismatch");std::cout<<"key_scene_geometry_changed_vertices="<<count<<" missing_asset_diagnostics="<<before.missingAssets.size()<<" warning="<<missingSummary<<" layer="<<layer<<" root_tick="<<rootTick<<" undo_restores_exact=true\n";return 0;}catch(const std::exception&e){std::cerr<<e.what()<<'\n';return 1;}}
